mapper.update:
UPDATE manga_creative_step
SET status = 'COMPLETED', output_json = #{outputJson}, lease_until = NULL,
    finished_at = #{finishedAt}, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'RUNNING'
  AND owner_instance_id = #{ownerInstanceId} AND owner_epoch = #{ownerEpoch}

UPDATE manga_creative_step
SET lease_until = #{leaseUntil}, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'RUNNING'
  AND owner_instance_id = #{ownerInstanceId} AND owner_epoch = #{ownerEpoch}
  AND lease_until > #{now}

UPDATE manga_creative_step
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage},
    lease_until = NULL, finished_at = #{finishedAt}, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'RUNNING'
  AND owner_instance_id = #{ownerInstanceId} AND owner_epoch = #{ownerEpoch}

UPDATE manga_creative_step
SET status = 'CANCELLED', lease_until = NULL, finished_at = #{finishedAt}, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'CANCEL_REQUESTED'
  AND owner_instance_id = #{ownerInstanceId} AND owner_epoch = #{ownerEpoch}

UPDATE manga_creative_step
SET status = 'CANCELLED', lease_until = NULL, finished_at = #{finishedAt}, updated_by = #{updatedBy}
WHERE run_id = #{runId}
  AND status IN ('PENDING', 'READY', 'WAITING_APPROVAL', 'WAITING_JOB', 'WAITING_CHILDREN', 'WAITING_RETRY')

UPDATE manga_creative_step
SET status = 'CANCEL_REQUESTED', updated_by = #{updatedBy}
WHERE run_id = #{runId} AND status = 'RUNNING'

UPDATE manga_creative_step
SET status = 'READY', schedule_version = schedule_version + 1,
    owner_instance_id = NULL, lease_until = NULL, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'RUNNING'
  AND owner_epoch = #{ownerEpoch} AND lease_until <= #{now}
  AND attempt_no < max_attempts

UPDATE manga_creative_step
SET status = 'CANCELLED', lease_until = NULL, finished_at = #{now}, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'CANCEL_REQUESTED'
  AND owner_epoch = #{ownerEpoch} AND lease_until <= #{now}

UPDATE manga_creative_step
SET status = 'FAILED', lease_until = NULL, finished_at = #{now},
    error_code = #{errorCode}, error_message = #{errorMessage}, updated_by = #{updatedBy}
WHERE step_id = #{stepId} AND status = 'RUNNING'
  AND owner_epoch = #{ownerEpoch} AND lease_until <= #{now}
  AND attempt_no >= max_attempts

mapper.select:
SELECT COUNT(*) FROM manga_creative_step
WHERE run_id = #{runId}
  AND status NOT IN ('COMPLETED', 'FAILED', 'CANCELLED', 'SKIPPED')
